def count_random_pictures(n, m):
    MOD = 10**9 + 7

    def dp(i, j, last):
        if i == n:
            return 1
        if j == m:
            return dp(i + 1, 0, last)

        res = dp(i, j + 1, 0)
        if last != 2:
            res += dp(i, j + 1, 1)
            if j > 0:
                res += dp(i, j + 1, 2)

        return res % MOD

    return dp(0, 0, 0)

