def count_random_pictures(n, m):
    if m == 1:
        return pow(2, n, MOD)
    else:
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            dp[i][0] = 1
            for j in range(1, min(i + 1, m) + 1):
                dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % MOD
                if j < i:
                    dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
                elif j > i:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
        return dp[n][m]

